async def parse_list(page):
    datasets = await page.query_selector_all("div[data-testid='dataset-list'] > div.dataset-item")
    for dataset in datasets:
        title = await dataset.query_selector_eval('h2.dataset-title', 'el => el.textContent.trim()')
        detail_url = await dataset.query_selector_eval('a.dataset-link', 'el => el.href')
        yield {'title': title, 'detail_url': detail_url}

async def parse_list(page):
    items = await page.query_selector_all('ul li')
    for item in items:
        detail_link = await item.query_selector_eval('a', 'a => a.href')
        yield {'detail_url': detail_link}

